18	 */
19	@Repository
20	public class RideRepository {
21	
22	    private static final RowMapper<Ride> MAPPER = (rs, rowNum) -> map(rs);
23	
24	    private final JdbcTemplate jdbc;
25	
26	    public RideRepository(JdbcTemplate jdbc) {
27	        this.jdbc = jdbc;
28	    }
