30	    private static Ride map(ResultSet rs) throws SQLException {
31	        Date checkDate = rs.getDate("check_date");
32	        Date reopenDate = rs.getDate("reopen_date");
33	        return new Ride(
34	                rs.getLong("id"),
35	                rs.getString("name"),
36	                RideStatus.valueOf(rs.getString("status")),
37	                rs.getInt("max_load"),
38	                rs.getInt("max_speed"),
39	                rs.getInt("trial_count"),
40	                rs.getInt("reopen_count"),
41	                checkDate == null ? null : checkDate.toLocalDate(),
42	                reopenDate == null ? null : reopenDate.toLocalDate(),
43	                rs.getBoolean("inspection_required"),
44	                rs.getLong("overhaul_version"),
45	                rs.getLong("version"));
46	    }
47	
48	    /** 插入新设备，初始状态为待日检；inspectionRequired 为受检标志，旧设备传 false 行为不变。 */
49	    public Ride insert(String name, int maxLoad, int maxSpeed, boolean inspectionRequired) {
50	        KeyHolder keyHolder = new GeneratedKeyHolder();
51	        jdbc.update(con -> {
52	            PreparedStatement ps = con.prepareStatement(
53	                    "INSERT INTO ride (name, status, max_load, max_speed, inspection_required)"
54	                            + " VALUES (?, ?, ?, ?, ?)",
55	                    new String[]{"id"});
56	            ps.setString(1, name);
57	            ps.setString(2, RideStatus.PENDING_CHECK.name());
58	            ps.setInt(3, maxLoad);
59	            ps.setInt(4, maxSpeed);
60	            ps.setBoolean(5, inspectionRequired);
61	            return ps;
62	        }, keyHolder);
63	        long id = keyHolder.getKey().longValue();
64	        return findById(id).orElseThrow();
65	    }
66	
67	    public Optional<Ride> findById(long id) {
68	        return jdbc.query("SELECT * FROM ride WHERE id = ?", MAPPER, id)
69	                .stream().findFirst();
70	    }
71	
72	    /** 行级悲观锁读取：同事务内串行化同一设备的状态流转。 */
73	    public Optional<Ride> findByIdForUpdate(long id) {
74	        return jdbc.query("SELECT * FROM ride WHERE id = ? FOR UPDATE", MAPPER, id)
75	                .stream().findFirst();
76	    }
77	
78	    /**
79	     * 乐观锁更新：仅当版本号匹配时写入，返回是否成功。
80	     * 并发下只有一条状态链能生效。
81	     */
82	    public boolean updateWithVersion(Ride ride, RideStatus newStatus, int trialCount,
83	            int reopenCount, LocalDate checkDate, LocalDate reopenDate) {
84	        int rows = jdbc.update(
85	                "UPDATE ride SET status = ?, trial_count = ?, reopen_count = ?,"
86	                        + " check_date = ?, reopen_date = ?, version = version + 1"
87	                        + " WHERE id = ? AND version = ?",
88	                newStatus.name(), trialCount, reopenCount,
89	                checkDate == null ? null : Date.valueOf(checkDate),
90	                reopenDate == null ? null : Date.valueOf(reopenDate),
91	                ride.id(), ride.version());
92	        return rows == 1;
93	    }
94	
95	    /**
96	     * 登记大修：原子递增检验周期版本（大修版本）并同步状态（开放中则暂停开放），
97	     * 仅当设备乐观锁版本匹配时写入，保证大修与开放竞态下资格不失效仍新开放。
98	     */
99	    public boolean registerOverhaul(Ride ride, RideStatus newStatus, long newOverhaulVersion) {
100	        int rows = jdbc.update(
101	                "UPDATE ride SET status = ?, overhaul_version = ?, version = version + 1"
102	                        + " WHERE id = ? AND version = ?",
103	                newStatus.name(), newOverhaulVersion, ride.id(), ride.version());
104	        return rows == 1;
105	    }
106	}
